import {SimulationLibrary} from './simulation-library.js';
import {proposalInput,installSetupAgent} from './setup-agent.js';
import {episodeDates} from './m2c.js';
const esc=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
export function revisionState(jobs,modelId){const rows=jobs.filter(j=>j.recipe.modelId===modelId).sort((a,b)=>b.revision-a.revision);return {latest:rows[0],viewing:rows.find(j=>j.status==='complete'),next:(rows[0]?.revision||0)+1,rows};}
export function mergeJobs(local,remote){const byId=new Map(local.map(j=>[j.jobId,j]));for(const j of remote)byId.set(j.jobId,j);return [...byId.values()];}
export function formatETA(seconds){return seconds==null?'Estimating after the first district…':seconds<60?'About a minute remaining':`About ${Math.ceil(seconds/60)} minutes remaining`;}
export function codeMarkup(code){return [...code].map((c,i)=>`${i===4?'<span aria-hidden="true">–</span>':''}<b>${esc(c)}</b>`).join('');}
const messages=['Teaching the meters to count politely…','Finding the bill that fell behind the sofa…','Convincing the queues to form one orderly line…','Putting tiny hard hats on the maintenance plan…','Asking the spreadsheets to use their indoor voices…'];
if(typeof document!=='undefined'){
 const root=document.getElementById('local-root'),q=new URLSearchParams(location.search),fragment=new URLSearchParams(location.hash.slice(1)),api=(q.get('engine')||'').replace(/\/$/,'')+'/api';
 const library=new SimulationLibrary();let detailQuery=null,detailData=null;let modelId=q.get('model'),model=library.get(modelId||''),token=fragment.get('workspace')||localStorage.getItem('utility-local-workspace'),available=false,devices=[],jobs=[],pair=null,scenarios=[],error='',busy=false,voice=false,closeVoice,viewRevision=null,shownJobId=null;
 if(fragment.has('workspace')){localStorage.setItem('utility-local-workspace',token);history.replaceState(null,'',location.pathname+location.search);}
 const savedKey=()=> 'utility-local-jobs:'+(token?.split('.')[0]||'manual');
 try{jobs=JSON.parse(localStorage.getItem(savedKey())||'[]');}catch{error='The local job list could not be read.';}
 function remember(){try{localStorage.setItem(savedKey(),JSON.stringify(jobs));}catch{error='Browser storage is full. Download your job and result summaries to keep a copy.';}}
 async function request(path,data,auth=true){const r=await fetch(api+'/portal/'+path,{method:data===undefined?'GET':'POST',headers:{'Content-Type':'application/json',...(auth&&token?{Authorization:'Bearer '+token}:{})},body:data===undefined?undefined:JSON.stringify(data),signal:AbortSignal.timeout(20000)});let result;try{result=await r.json();}catch{throw Error('Studio could not read the server response.');}if(!r.ok)throw Error(typeof result.detail==='string'?result.detail:'This request could not be accepted.');return result;}
 function download(value,name){const url=URL.createObjectURL(new Blob([JSON.stringify(value,null,2)],{type:'application/json'})),a=document.createElement('a');a.href=url;a.download=name;a.click();setTimeout(()=>URL.revokeObjectURL(url),1000);}
 function setModel(id){modelId=id;const existing=library.get(id);if(existing){model=existing;return;}const latest=revisionState(jobs,id).latest;if(latest){const p=latest.recipe.proposal;model=library.save({...library.create(),...p,id,status:'ready',execution:'local',homes:latest.recipe.homes,totalHomes:latest.recipe.homes,townRef:p.townRef||'',scenarioId:'custom',scenarioTitle:'Saved local setup'});}}
 async function refresh(renderPage=true){try{if(detailQuery){const d=await request('details/'+detailQuery);if(d.status==='complete'){detailQuery=null;if(d.error)throw Error(d.error);detailData=d.result;}} const status=await request('status',undefined,false);available=status.available;if(available&&token){const state=await request('workspace');jobs=mergeJobs(jobs,state.jobs);devices=state.devices;remember();if(!model&&jobs.length)setModel(jobs.at(-1).recipe.modelId);}}catch(e){error=e.message;}if(renderPage&&!voice&&!busy&&!['INPUT','SELECT','TEXTAREA'].includes(document.activeElement?.tagName))render();updateMonitor();}
 function updateMonitor(){const el=document.getElementById('local-monitor'),active=jobs.find(j=>['running','queued'].includes(j.status));el.hidden=!active;if(!active)return;const p=active.progress||{},queued=jobs.filter(j=>j.status==='queued').length;el.innerHTML=`<strong>${esc(active.recipe.name)} · revision ${active.revision}</strong><p>${active.status==='queued'?'Waiting for a connected computer':esc(p.stage||'Preparing the engine')}</p><progress max="${p.total||1}" value="${p.completed||0}"></progress><p>${p.completed||0}/${p.total||Math.ceil(active.recipe.homes/active.recipe.chunkSize)} districts · ${queued} queued</p><p>${esc(formatETA(p.etaSeconds))}</p><small>${messages[Math.floor(Date.now()/9000)%messages.length]}</small>`;}
 function currentProposal(){return {...proposalInput(model),execution:'local',totalHomes:model.totalHomes||model.homes,summary:model.summary||'Run this environment and utility locally.'};}
 async function queue(){if(busy)return;busy=true;error='';render();try{const state=revisionState(jobs,modelId);const file=await request('prepare',{proposal:currentProposal(),modelId,staffing:'independent-districts',revision:state.next,chunkSize:2000},false);let job;if(available){if(!token){const created=await request('workspaces',{},false);token=created.token;localStorage.setItem('utility-local-workspace',token);}job=await request('jobs',file);}else job={...file,status:'manual',progress:{},result:null};jobs=mergeJobs(jobs,[job]);remember();}catch(e){error=e.message;}finally{busy=false;render();}}
 function view(){const state=revisionState(jobs,modelId),selected=state.rows.find(j=>j.revision===Number(viewRevision)&&j.status==='complete');return {state,job:selected||state.viewing};}
 function render(){if(voice)return;const {state,job}=view(),rollup=job?.result?.rollup;if(shownJobId!==job?.jobId){detailData=null;detailQuery=null;shownJobId=job?.jobId;}const models=[...new Map(jobs.map(j=>[j.recipe.modelId,j.recipe.name])).entries()];if(model&&!models.some(([id])=>id===model.id))models.push([model.id,model.name]);
 document.getElementById('config-link').href='./?edit='+encodeURIComponent(modelId||'')+(q.get('engine')?'&engine='+encodeURIComponent(q.get('engine')):'');
 root.innerHTML=`<div class="eyebrow">YOUR COMPUTER · YOUR DATA</div><h1>${esc(model?.name||'Local simulations')}</h1><p>Configure here. Process locally. Keep full results on your chosen drive.</p><p id="portal-error" role="alert">${esc(error)}</p>${models.length>1?`<label>Simulation<select id="model-picker">${models.map(([id,name])=>`<option value="${esc(id)}" ${id===modelId?'selected':''}>${esc(name)}</option>`).join('')}</select></label>`:''}<section><h2>Connected computers</h2>${available?devices.map(d=>`<p><strong>${esc(d.name)}</strong> · ${d.online?'Online':'Offline'} <button class="text-button" data-revoke="${esc(d.id)}">Disconnect</button></p>`).join('')||'<p>Connect your computer to receive jobs automatically.</p>':'<p>Automatic pairing and sync are not configured on this Studio yet. Download a job below and import it in the runner.</p>'}<div class="download-list"><a class="primary" href="https://github.com/gragedmonds/utiltiysim/releases/latest" target="_blank" rel="noopener">Download local runner ↗</a>${available?'<button class="secondary" id="pair-button">Connect a computer</button>':''}${token?'<button class="text-button" id="share-link">Copy workspace link</button>':''}</div>${pair?`<div class="code-display" aria-label="Pairing code ${esc(pair.code)}">${codeMarkup(pair.code)}</div><p>Enter this in the runner. Expires ${new Date(pair.expiresAt*1000).toLocaleTimeString()}. Each code connects one computer.</p>`:''}<p class="local-note">Install once, choose a folder such as P:\\UtilitySim, then reconnect automatically. A workspace link grants access to its configurations, jobs and summaries.</p></section>${model?`<section><h2>Configuration &amp; run</h2><p><strong>${Number(model.totalHomes||model.homes).toLocaleString()} residential homes</strong> · local batches of up to 2,000 · model year 2026</p><p class="local-note">This mode uses independent districts. Analysts and agents are per district; per-1,000 crew settings scale within each district. Districts do not share a utility-wide workforce or connected network. Commercial sites add accounts.</p><label><input id="staffing-confirm" type="checkbox" ${model.staffingAcknowledged?'checked':''}> I’m modelling independent district teams.</label><button id="queue-run" class="primary" ${busy?'disabled':''}>${busy?'Checking inputs…':`Run revision ${state.next} locally`}</button><p>${available?'If the computer is offline, the job waits here.':'Download the job after preparing it. Full databases are generated locally.'}</p></section>`:'<p>Start a simulation in <a href="./">the setup wizard</a>, or import a job file below.</p>'}<section><h2>Your revisions</h2><p class="revision-line">${job?`Viewing revision ${job.revision}`:'No completed results yet'}${state.latest&&state.latest!==job?` · revision ${state.latest.revision} ${esc(state.latest.status)}`:''}</p>${state.rows.map(j=>`<div class="local-tabs"><strong>Revision ${j.revision}</strong><span>${esc(j.status==='manual'?'Awaiting manual processing':j.status)}</span><button class="text-button" data-job="${j.jobId}">Download job</button>${j.status==='complete'?`<button class="text-button" data-view="${j.revision}">View results</button><button class="text-button" data-result="${j.jobId}">Download summary</button>`:''}${j.status==='failed'?`<span>${esc(j.error)}</span><button data-retry="${j.jobId}" class="text-button">Retry</button>`:''}</div>`).join('')||'<p>Your first job will appear here.</p>'}<label>Import a job or result summary<input id="import-result" type="file" accept=".json,application/json"></label></section>${model?`<section><h2>Inflict a change</h2><p>A tweak creates a new revision. Your completed results remain available while it processes.</p><div class="local-grid"><label>Start<input id="inflict-start" type="date" min="2026-01-01" max="2026-12-31" value="${esc(model.asOf)}"></label><label>Scenario<select id="inflict-scenario">${scenarios.map(s=>`<option value="${esc(s.id)}">${esc(s.title)}</option>`).join('')}</select></label></div><button class="secondary" id="inflict" ${scenarios.length?'':'disabled'}>Add scenario &amp; queue revision</button><button class="text-button" id="voice-tweak">Talk through a tweak</button><p class="local-note">Scenario changes reuse the saved baseline. Environment changes build a new baseline. Annual analysis may still replay the full year.</p></section>`:''}${rollup?`<section><h2>Year · revision ${job.revision}</h2><p>${rollup.accounts.toLocaleString()} accounts · ${rollup.registers.toLocaleString()} registers · ${rollup.completedDistricts} districts · results through ${esc(rollup.asOf)}</p><div class="local-months">${rollup.months.map(m=>`<article class="month-card"><span>${['January','February','March','April','May','June','July','August','September','October','November','December'][Number(m.month)-1]||esc(m.month)}</span><strong>${Number(m.billing.invoiced||0).toLocaleString(undefined,{maximumFractionDigits:0})}</strong><small>Invoiced · ${Number(m.cases.backlog||0).toLocaleString()} open cases</small></article>`).join('')}</div><details><summary>Where the engine spent time</summary><table><tbody>${Object.entries(job.result.timings.stagesSeconds||{}).sort((a,b)=>b[1]-a[1]).map(([name,seconds])=>`<tr><td>${esc(name)}</td><td>${Number(seconds).toFixed(2)}s</td></tr>`).join('')}</tbody></table></details><p>These are additive district totals. Full data tables remain on the computer that processed this revision.</p><a href="./runs.html">Open a downloaded district folder →</a><div id="detail-panel"><h3>Request saved detail</h3><p class="local-note">Fetch one page from the computer holding this revision. It must be online. Manual imports can be opened in the local folder reader.</p><div class="local-grid"><label>District<select id="detail-district">${job.result.districts.map(d=>`<option value="${d.runKey}">${esc(d.id)}</option>`).join('')}</select></label><label>Table<select id="detail-table">${['accounts','reads','billingDocuments','invoices','cases','contacts','fieldOrders','ledger'].map(t=>`<option>${t}</option>`).join('')}</select></label><label>Search<input id="detail-search" maxlength="100"></label><label>Page<input id="detail-page" type="number" value="1" min="1" max="100000"></label></div><button id="request-detail" class="secondary">Request page</button>${detailQuery?'<p>Waiting for the computer…</p>':''}${detailData?`<p>${esc(detailData.table)} · ${detailData.total} rows · page ${detailData.page}</p><div class="local-scroll"><table><thead><tr>${detailData.columns.map(c=>`<th>${esc(c.label||c.key)}</th>`).join('')}</tr></thead><tbody>${detailData.rows.map(row=>`<tr>${row.map(v=>`<td>${esc(v)}</td>`).join('')}</tr>`).join('')}</tbody></table></div>`:''}</div></section>`:''}`;
 const $=id=>document.getElementById(id),action=fn=>async()=>{try{error='';await fn();}catch(e){error=e.message;}if(!voice)render();};
 if($('request-detail'))$('request-detail').onclick=action(async()=>{if(!available||!token)throw Error('Use the local saved-results reader while sync is unavailable.');detailData=null;detailQuery=(await request('details',{jobId:job.jobId,runKey:$('detail-district').value,table:$('detail-table').value,search:$('detail-search').value,page:Number($('detail-page').value)})).id;});
 if($('model-picker'))$('model-picker').onchange=e=>{setModel(e.target.value);viewRevision=null,shownJobId=null;render();};
 if($('staffing-confirm'))$('staffing-confirm').onchange=e=>{model=library.update(model.id,{staffingAcknowledged:e.target.checked});};
 if($('queue-run'))$('queue-run').onclick=action(async()=>{if(!$('staffing-confirm').checked)throw Error('Confirm that staffing applies to independent districts before running.');await queue();});
 if($('pair-button'))$('pair-button').onclick=action(async()=>{if(!token){const created=await request('workspaces',{},false);token=created.token;localStorage.setItem('utility-local-workspace',token);}pair=await request('pairings',{});});
 if($('share-link'))$('share-link').onclick=action(async()=>{const url=new URL(location.href);url.searchParams.set('model',modelId);url.hash='workspace='+encodeURIComponent(token);await navigator.clipboard.writeText(url.href);error='Workspace link copied.';});
 root.querySelectorAll('[data-revoke]').forEach(b=>b.onclick=action(async()=>{await request('devices/'+b.dataset.revoke+'/revoke',{});await refresh(false);}));
 root.querySelectorAll('[data-job]').forEach(b=>b.onclick=()=>{const j=jobs.find(j=>j.jobId===b.dataset.job);download(Object.fromEntries(['schemaVersion','jobId','revision','recipeKey','recipe'].map(k=>[k,j[k]])),`${j.jobId}.job.json`);});
 root.querySelectorAll('[data-view]').forEach(b=>b.onclick=()=>{viewRevision=Number(b.dataset.view);render();});
 root.querySelectorAll('[data-result]').forEach(b=>b.onclick=()=>{const j=jobs.find(j=>j.jobId===b.dataset.result);download(j.result,`${j.jobId}.result.json`);});
 root.querySelectorAll('[data-retry]').forEach(b=>b.onclick=action(async()=>{await request('jobs/'+b.dataset.retry+'/retry',{});await refresh(false);}));
 $('import-result').onchange=async e=>{try{const f=e.target.files[0];if(f.size>2000000)throw Error('Choose a small job or result JSON file.');const value=JSON.parse(await f.text());if(value.schemaVersion==='local-job-file/1.0'){if(available&&token){jobs=mergeJobs(jobs,[await request('jobs',value)]);}else{const r=await request('check-file',value,false);jobs=mergeJobs(jobs,[{...r,status:'manual',result:null}]);}setModel(value.recipe.modelId);}else{const job=jobs.find(j=>j.jobId===value.jobId);if(!job)throw Error('Import the matching job file first.');const validated=await request('check-result',{job,result:value},false);if(available&&token){jobs=mergeJobs(jobs,[await request('results/import',validated)]);}else{job.status='complete';job.result=validated;}}remember();render();}catch(e){error=e.message;render();}};
 if($('inflict'))$('inflict').onclick=action(async()=>{const scenario=scenarios.find(s=>s.id===$('inflict-scenario').value),start=$('inflict-start').value;if(!start||!$('inflict-start').checkValidity())throw Error('Choose a date in 2026.');const added=episodeDates(scenario,start).map((ep,i)=>({...ep,id:'EP-'+crypto.randomUUID()}));model=library.update(model.id,{episodes:[...(model.episodes||[]),...added],asOf:[model.asOf,...added.map(e=>e.to||'2026-12-31')].sort().at(-1)});await queue();});
 if($('voice-tweak'))$('voice-tweak').onclick=()=>{voice=true;root.innerHTML='<div id="voice-root"></div>';closeVoice=installSetupAgent({root:$('voice-root'),api,getDraft:()=>({...model,startDate:model.asOf}),onSave:()=>{},mode:'inflict',onBack:()=>{closeVoice?.();voice=false;render();},onApply:async proposal=>{model=library.update(model.id,{episodes:[...(model.episodes||[]),...proposal.episodes.map(ep=>({...ep,id:'EP-'+crypto.randomUUID()}))],asOf:proposal.runTo});closeVoice?.();voice=false;await queue();}});};
 }
 try{const r=await fetch(api+'/m2c/scenarios');if(r.ok)scenarios=(await r.json()).scenarios;}catch{}
 await refresh();setInterval(()=>refresh(),5000);
}
